import datetime

with open('/app/logs/auditd.log') as f:
    text = f.read()

records = text.strip().split('\n\n')
for i, rec in enumerate(records):
    lines = rec.strip().split('\n')
    ts = None
    msg_type = ''
    for l in lines:
        if 'msg=audit(' in l:
            epoch = float(l.split('msg=audit(')[1].split(':')[0])
            ts = datetime.datetime.fromtimestamp(epoch, datetime.timezone.utc).strftime('%Y-%m-%d %H:%M:%S.%f')
        if 'type=' in l:
            t = l.split('type=')[1].split(' ')[0]
            msg_type += t + ' '
    print(f'Rec {i+1}: {ts} | Types: {msg_type.strip()}')
    for l in lines:
        print('   ', l)
""}

