import json, csv

events = []

# 1. pip_packages.json
with open('/app/logs/pip_packages.json') as f:
    data = json.load(f)
    for p in data['packages']:
        events.append({
            'ts': p['install_time'],
            'source': 'pip',
            'event_type': 'package_install',
            'details': f\"Pip installed package '{p['name']}' version {p['version']}\"
        })

# 2. dpkg.log
with open('/app/logs/dpkg.log') as f:
    for line in f:
        line = line.strip()
        if not line: continue
        parts = line.split(' ')
        if len(parts) >= 5 and parts[2] == 'install':
            events.append({
                'ts': f\"{parts[0]} {parts[1]}\",
                'source': 'dpkg',
                'event_type': 'package_install',
                'details': f\"Installed debian package {parts[3]}\"
            })

# 3. dns_queries.log
with open('/app/logs/dns_queries.log') as f:
    reader = csv.DictReader(f)
    for row in reader:
        events.append({
            'ts': row['timestamp'],
            'source': 'dns',
            'event_type': 'dns_query',
            'details': f\"DNS query for {row['query_name']} resolved to {row['response_ip']}\"
        })

# 4. netflow.csv
with open('/app/logs/netflow.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        # Categorize exfiltration or network_connection
        ev_type = 'network_connection'
        if row['dst_ip'] == '104.152.171.76' and int(row['bytes_sent']) > 500 and '11:02' <= row['timestamp'][11:16] <= '11:05':
            ev_type = 'exfiltration'
        events.append({
            'ts': row['timestamp'],
            'source': 'netflow',
            'event_type': ev_type,
            'details': f\"Network flow {row['src_ip']}:{row['src_port']} -> {row['dst_ip']}:{row['dst_port']} ({row['protocol']}, sent: {row['bytes_sent']}B, recv: {row['bytes_recv']}B, state: {row['connection_state']})\"
        })

# 5. journal.log
with open('/app/logs/journal.log') as f:
    for line in f:
        line = line.strip()
        if not line: continue
        parts = line.split(' ', 4)
        if len(parts) >= 5:
            ts = f\"2024-03-15 {parts[2]}\"
            msg = parts[4]
            ev_type = 'service_event'
            if 'pip install' in msg:
                ev_type = 'package_install'
            elif 'Creating systemd user service' in msg or 'Creating helper binary' in msg or 'Modifying /home/developer/.profile' in msg:
                ev_type = 'persistence'
            elif 'Reading ' in msg or 'Attempting to read' in msg:
                ev_type = 'file_read'
            elif 'Upload' in msg or 'Diagnostic report submitted' in msg:
                ev_type = 'exfiltration'
            events.append({
                'ts': ts,
                'source': 'journal',
                'event_type': ev_type,
                'details': msg
            })

# 6. auditd.log
with open('/app/logs/auditd.log') as f:
    # Process auditd line by line, grouping by msg=audit(epoch:seq)
    curr_msg = None
    curr_lines = []
    for line in f:
        line = line.strip()
        if not line: continue
        msg_id = line.split('msg=audit(')[1].split(')')[0] if 'msg=audit(' in line else None
        if msg_id != curr_msg:
            if curr_lines:
                # process group
                epoch = float(curr_lines[0].split('msg=audit(')[1].split(':')[0])
                sec_from_midnight = epoch - 1710459600
                m, s = divmod(sec_from_midnight, 60)
                h, m = divmod(m, 60)
                ts = f\"2024-03-15 {int(h):02d}:{int(m):02d}:{int(s):02d}\"

                # deduce type & details
                exec_line = next((l for l in curr_lines if 'type=EXECVE' in l), None)
                path_line = next((l for l in curr_lines if 'type=PATH' in l), None)
                syscall_line = next((l for l in curr_lines if 'type=SYSCALL' in l), None)

                ev_type = 'process_exec'
                details = ''
                if exec_line:
                    ev_type = 'process_exec'
                    # extract args
                    args = []
                    for item in exec_line.split():
                        if item.startswith('a0=') or item.startswith('a1=') or item.startswith('a2=') or item.startswith('a3='):
                            args.append(item.split('=', 1)[1].strip('\"'))
                    details = f\"Executed process: {' '.join(args)}\"
                    if '.pth_loader.py' in details:
                        ev_type = 'process_exec' # or malicious post-install execution
                elif path_line and syscall_line:
                    pathname = path_line.split('name=')[1].split()[0].strip('\"')
                    if 'key=\"file_write\"' in syscall_line or 'nametype=CREATE' in path_line:
                        if '.config/systemd' in pathname or '.local/bin' in pathname or '.profile' in pathname:
                            ev_type = 'persistence'
                        else:
                            ev_type = 'file_write'
                        details = f\"File written: {pathname}\"
                    elif 'key=\"file_read\"' in syscall_line:
                        ev_type = 'file_read'
                        details = f\"File read: {pathname}\"
                elif syscall_line and 'key=\"network\"' in syscall_line:
                    ev_type = 'network_connection'
                    details = f\"Network syscall by pid {syscall_line.split('pid=')[1].split()[0]}\"

                if details:
                    events.append({
                        'ts': ts,
                        'source': 'auditd',
                        'event_type': ev_type,
                        'details': details
                    })
            curr_msg = msg_id
            curr_lines = [line]
        else:
            curr_lines.append(line)

events.sort(key=lambda x: x['ts'])
print(f'Total events: {len(events)}')
for e in events:
    if e['ts'] >= '2024-03-15 10:40:00':
        print(f\"{e['ts']} | {e['source']:7s} | {e['event_type']:18s} | {e['details']}\")
""}
